#include "../common.h"
int main(void){char key[100],s[500],alpha[]="ABCDEFGHIJKLMNOPQRSTUVWXYZ",map[27]="";int used[26]={0},n=0;printf("Keyword: ");scanf("%99s",key);upper_letters(key);for(int i=0;key[i];i++)if(isalpha(key[i])&&!used[key[i]-'A']){map[n++]=key[i];used[key[i]-'A']=1;}for(int i=0;i<26;i++)if(!used[i])map[n++]=alpha[i];map[26]=0;getchar();printf("Plaintext: ");fgets(s,sizeof s,stdin);for(int i=0;s[i];i++)if(isalpha((unsigned char)s[i])){int u=isupper((unsigned char)s[i]);char x=map[toupper(s[i])-'A'];s[i]=u?x:tolower(x);}printf("Cipher alphabet: %s\nCiphertext: %s",map,s);}
